// LoadCountPurchaseItemTags loads the count of PurchaseItemTags for a slice in a single batch query
func (os TagSlice) LoadCountPurchaseItemTags(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	// Build the IN arg expression from parent PKs

	pkHouseholdID := make(pgtypes.Array[uuid.UUID], 0, len(os))
	pkID := make(pgtypes.Array[uuid.UUID], 0, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}
		pkHouseholdID = append(pkHouseholdID, o.HouseholdID)
		pkID = append(pkID, o.ID)
	}

	// countResult holds one scanned row from the batch count query.
	// FK columns are aliased to the parent PK column names for direct map lookup.
	type countResult struct {
		HouseholdID uuid.UUID

		ID    uuid.UUID
		Count int64
	}

	batchMods := []bob.Mod[*dialect.SelectQuery]{
		// SELECT fk AS parent_pk, count(*)
		sm.Columns(
			PurchaseItemTags.Columns.HouseholdID.As("household_id"),
			PurchaseItemTags.Columns.TagID.As("id"),
			psql.Raw("count(*) as count"),
		),
		// Single-hop: FROM related table directly
		sm.From(PurchaseItemTags.NameAsExpr()),

		// WHERE fk IN (parent PKs) — psql single-column FK uses `= ANY(array)` (see PKArgExpr above)
		sm.InnerJoin(psql.Select(
			sm.Distinct(),
			sm.Columns(
				psql.Quote("bob_rel_keys_src", "HouseholdID"),
				psql.Quote("bob_rel_keys_src", "TagID"),
			),
			sm.From(psql.F("unnest",
				psql.Cast(psql.Arg(pkHouseholdID), "uuid[]"),
				psql.Cast(psql.Arg(pkID), "uuid[]"),
			)).As("bob_rel_keys_src", "HouseholdID", "TagID"),
		)).As("bob_rel_keys").On(
			PurchaseItemTags.Columns.HouseholdID.EQ(psql.Quote("bob_rel_keys", "HouseholdID")),
			PurchaseItemTags.Columns.TagID.EQ(psql.Quote("bob_rel_keys", "TagID")),
		),
		// GROUP BY fk columns
		sm.GroupBy(PurchaseItemTags.Columns.HouseholdID),
		sm.GroupBy(PurchaseItemTags.Columns.TagID),
	}
	batchMods = append(batchMods, mods...)

	results, err := bob.All(ctx, exec,
		psql.Select(batchMods...),
		scan.StructMapper[countResult](),
	)
	if err != nil {
		return err
	}

	// Composite FK: use a key struct
	type countKey struct {
		HouseholdID uuid.UUID

		ID uuid.UUID
	}
	countMap := make(map[countKey]int64, len(results))
	for _, r := range results {
		countMap[countKey{
			HouseholdID: r.HouseholdID,

			ID: r.ID,
		}] = r.Count
	}
	for _, o := range os {
		if o == nil {
			continue
		}
		count := countMap[countKey{
			HouseholdID: o.HouseholdID,

			ID: o.ID,
		}]
		o.C.PurchaseItemTags = &count
	}

	return nil
}

type tagJoins[Q dialect.Joinable] struct {
	typ              string
	PurchaseItemTags modAs[Q, purchaseItemTagColumns]
	Household        modAs[Q, householdColumns]
}

func (j tagJoins[Q]) aliasedAs(alias string) tagJoins[Q] {
	return buildTagJoins[Q](buildTagColumns(alias), j.typ)
}

func buildTagJoins[Q dialect.Joinable](cols tagColumns, typ string) tagJoins[Q] {
	return tagJoins[Q]{
		typ: typ,
		PurchaseItemTags: modAs[Q, purchaseItemTagColumns]{
			c: PurchaseItemTags.Columns,
			f: func(to purchaseItemTagColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, PurchaseItemTags.NameExpr().As(to.Alias())).On(
						to.HouseholdID.EQ(cols.HouseholdID), to.TagID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		Household: modAs[Q, householdColumns]{
			c: Households.Columns,
			f: func(to householdColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Households.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.HouseholdID),
					))
				}

				return mods
			},
		},
	}
}
